#pragma once

static const char JRBOT_WEB_V1_HTML[]=
"<!doctype html><html lang='pt-br'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
"<title>JrBot V1</title><style>"
":root{color-scheme:dark;--bg:#0b0d10;--card:#15191f;--line:#252b33;--text:#f4f6f8;--muted:#9099a6;--ok:#79d69b;--bad:#ff8c8c}"
"*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui,-apple-system,Segoe UI,sans-serif}"
"main{max-width:760px;margin:auto;padding:24px 16px 48px}.top{display:flex;justify-content:space-between;gap:16px;margin-bottom:22px}h1{font-size:26px;margin:0 0 5px}.sub{color:var(--muted);font-size:13px}"
".dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--bad);margin-right:7px}.dot.ok{background:var(--ok)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:18px}"
".stat,.card{background:var(--card);border:1px solid var(--line);border-radius:14px}.stat{padding:13px}.stat small{display:block;color:var(--muted);margin-bottom:5px}.card{padding:18px;margin:12px 0}.card h2{font-size:16px;margin:0 0 14px}.faces{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}"
"button,a.action{border:1px solid var(--line);background:#20262e;color:var(--text);border-radius:10px;padding:11px 12px;font:inherit;cursor:pointer;text-decoration:none;text-align:center}.primary{background:#f4f6f8;color:#111}.row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.grow{flex:1}input[type=range]{width:100%}select{background:#20262e;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:10px}audio{width:100%;margin-top:12px}.feedback{min-height:20px;color:var(--muted);font-size:13px;margin:16px 2px}.feedback.err{color:var(--bad)}details{margin-top:9px;color:var(--muted)}.more{padding-top:10px}.foot{color:var(--muted);font-size:12px;margin-top:22px;border-top:1px solid var(--line);padding-top:14px}@media(max-width:580px){.grid{grid-template-columns:1fr 1fr}.faces{grid-template-columns:repeat(2,1fr)}}"
"</style></head><body><main>"
"<div class='top'><div><h1>JrBot</h1><div class='sub'>V1 · Painel interno · JRBOT-WEB-V1-01</div></div><div class='sub'><span id='dot' class='dot'></span><span id='conn'>Conectando</span></div></div>"
"<div class='grid'><div class='stat'><small>Face</small><b id='face'>—</b></div><div class='stat'><small>Volume</small><b id='volume'>—</b></div><div class='stat'><small>Microfone</small><b id='mic'>—</b></div><div class='stat'><small>Wi-Fi</small><b id='wifi'>—</b></div><div class='stat'><small>IP</small><b id='ip'>—</b></div><div class='stat'><small>Firmware</small><b id='fw'>—</b></div></div>"
"<section class='card'><h2>Rosto</h2><div id='faces-main' class='faces'></div><details><summary>Mais expressões</summary><div id='faces-more' class='faces more'></div></details></section>"
"<section class='card'><h2>Microfone</h2><div class='row'><label>Gravar</label><select id='seconds'><option value='1'>1 s</option><option value='3' selected>3 s</option><option value='5'>5 s</option><option value='10'>10 s</option></select><button id='record' class='primary' onclick='recordAudio()'>Gravar áudio</button></div><audio id='player' controls hidden></audio><div id='record-actions' class='row' style='margin-top:10px' hidden><a id='download' class='action grow'>Baixar WAV</a><button class='grow' onclick='runCommand(\"audio_play_recording\",\"Reproduzindo no JrBot\")'>Tocar no JrBot</button></div></section>"
"<section class='card'><h2>Som</h2><div class='row'><span>Volume</span><b id='vol-label'>35</b></div><input id='vol' type='range' min='0' max='100' value='35' oninput='document.getElementById(\"vol-label\").textContent=this.value'><div class='row' style='margin-top:12px'><button class='primary grow' onclick='applyVolume()'>Aplicar volume</button><button class='grow' onclick='runCommand(\"audio_test\",\"Teste de som enviado\")'>Testar som</button></div></section>"
"<div id='feedback' class='feedback'>Pronto.</div><div class='foot'>Controle local do próprio JrBot. Sem autenticação/TLS nesta versão: use somente na rede local confiável.</div>"
"<script>const mainFaces=[['neutro','Neutro'],['feliz','Feliz'],['pensando','Pensando'],['surpreso','Surpreso'],['triste','Triste'],['sono','Sono'],['amor','Amor'],['cool','Cool']];const moreFaces=[['animado','Animado'],['bravo','Bravo'],['cetico','Cético'],['confuso','Confuso'],['piscando','Piscando'],['brincalhao','Brincalhão'],['preocupado','Preocupado'],['bateria','Bateria']];let busy=false,recordUrl=null;function addFaces(id,list){const box=document.getElementById(id);for(const f of list){const b=document.createElement('button');b.textContent=f[1];b.onclick=()=>runCommand(f[0],'Face: '+f[1]);box.appendChild(b)}}addFaces('faces-main',mainFaces);addFaces('faces-more',moreFaces);function feedback(t,err=false){const e=document.getElementById('feedback');e.textContent=t;e.className='feedback'+(err?' err':'')}function parseStatus(t){const o={};for(const p of t.trim().split(/\\s+/)){const i=p.indexOf('=');if(i>0)o[p.slice(0,i)]=p.slice(i+1)}return o}function micName(v){return({available:'Disponível',unavailable:'Indisponível',unknown:'Indefinido',busy:'Em uso',error:'Erro'})[v]||v||'—'}async function send(c){const r=await fetch('/cmd',{method:'POST',headers:{'Content-Type':'text/plain','X-JrBot-Command':'1'},body:c});const t=await r.text();if(!r.ok)throw new Error(t);return t}async function runCommand(c,ok){if(busy)return;busy=true;try{await send(c);feedback(ok||'Comando executado');await refresh(true)}catch(e){feedback('Erro: '+e.message,true)}finally{busy=false}}async function applyVolume(){const v=document.getElementById('vol').value;await runCommand('audio_volume '+v,'Volume ajustado para '+v)}async function recordAudio(){if(busy)return;busy=true;const btn=document.getElementById('record');btn.disabled=true;feedback('Gravando...');try{const s=document.getElementById('seconds').value;const r=await fetch('/mic-record?seconds='+encodeURIComponent(s),{cache:'no-store'});if(!r.ok)throw new Error(await r.text());const blob=await r.blob();if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(blob);const player=document.getElementById('player');player.src=recordUrl;player.hidden=false;const dl=document.getElementById('download');dl.href=recordUrl;dl.download='jrbot-microfone.wav';document.getElementById('record-actions').hidden=false;feedback('Gravação concluída. Ouça aqui, baixe ou toque no JrBot.')}catch(e){feedback('Erro na gravação: '+e.message,true)}finally{btn.disabled=false;busy=false;await refresh(true)}}async function refresh(force=false){if(busy&&!force)return;try{const r=await fetch('/status',{cache:'no-store'});const t=await r.text();if(!r.ok)throw new Error(t);const s=parseStatus(t);document.getElementById('dot').className='dot ok';document.getElementById('conn').textContent='Online';document.getElementById('face').textContent=s.expression||'—';document.getElementById('volume').textContent=(s.volume||'—')+(s.volume?'%':'');document.getElementById('mic').textContent=micName(s.mic);document.getElementById('wifi').textContent=s.wifi==='1'?'Conectado':'Desconectado';document.getElementById('ip').textContent=s.ip||'—';document.getElementById('fw').textContent=s.version||'—';if(s.volume){document.getElementById('vol').value=s.volume;document.getElementById('vol-label').textContent=s.volume}}catch(e){document.getElementById('dot').className='dot';document.getElementById('conn').textContent='Offline';feedback('Sem resposta do JrBot: '+e.message,true)}}refresh();setInterval(()=>refresh(false),10000);</script></main></body></html>";
